const DRIVE_PATTERN = /^[A-Za-z]:/;

function requirePathString(value, label) {
  if (typeof value !== 'string' || value.length === 0) {
    throw new TypeError(`${label} must be a non-empty string`);
  }
  if (value.includes('\0')) {
    throw new Error(`${label} contains a null byte`);
  }
  return value;
}

function toForwardSlashes(path) {
  return path.replaceAll('\\', '/');
}

function hasDrivePrefix(path) {
  return DRIVE_PATTERN.test(path);
}

function isUncPath(path) {
  return path.startsWith('//');
}

export function canonicalize(path) {
  requirePathString(path, 'path');
  const normalized = toForwardSlashes(path);
  const driveMatch = normalized.match(DRIVE_PATTERN);
  const drivePrefix = driveMatch ? `${driveMatch[0].toUpperCase()}/` : '';
  const withoutDrive = drivePrefix ? normalized.slice(driveMatch[0].length) : normalized;
  const isAbsolute = withoutDrive.startsWith('/') || drivePrefix.length > 0;
  const segments = withoutDrive.split('/').filter(segment => segment.length > 0 && segment !== '.');
  const stack = [];

  for (const segment of segments) {
    if (segment === '..') {
      if (stack.length > 0 && stack[stack.length - 1] !== '..') {
        stack.pop();
      } else if (!isAbsolute) {
        stack.push('..');
      }
    } else {
      stack.push(segment);
    }
  }

  const absolutePrefix = drivePrefix || (withoutDrive.startsWith('/') ? '/' : '');
  const joined = stack.join('/');
  return joined.length === 0 && absolutePrefix.length === 0 ? '.' : absolutePrefix + joined;
}

function assertInsideRoot(rootPath, candidatePath) {
  const rootWithSep = rootPath.endsWith('/') ? rootPath : `${rootPath}/`;
  if (candidatePath !== rootPath && !candidatePath.startsWith(rootWithSep)) {
    const error = new Error(`path escapes sandbox root: ${candidatePath}`);
    error.code = 'PATH_OUTSIDE_ROOT';
    throw error;
  }
}

export function resolveSafe(root, entryPath) {
  requirePathString(root, 'root');
  requirePathString(entryPath, 'entryPath');

  const normalizedEntry = toForwardSlashes(entryPath);
  if (normalizedEntry.startsWith('/') || entryPath.startsWith('\\')) {
    const error = new Error('absolute entry paths are not allowed');
    error.code = 'ABSOLUTE_ENTRY_PATH';
    throw error;
  }
  if (hasDrivePrefix(normalizedEntry)) {
    const error = new Error('drive-prefixed entry paths are not allowed');
    error.code = 'DRIVE_ENTRY_PATH';
    throw error;
  }
  if (isUncPath(normalizedEntry)) {
    const error = new Error('UNC entry paths are not allowed');
    error.code = 'UNC_ENTRY_PATH';
    throw error;
  }

  const canonicalRoot = canonicalize(root);
  const candidate = canonicalize(`${canonicalRoot}/${normalizedEntry}`);
  assertInsideRoot(canonicalRoot, candidate);
  return candidate;
}

import { resolveSafe } from './pathGuard.js';

export function extractListing(entries, root) {
  if (!Array.isArray(entries)) {
    throw new TypeError('entries must be an array');
  }

  const ok = [];
  const blocked = [];

  for (const entry of entries) {
    const path = entry && typeof entry === 'object' ? entry.path : undefined;
    try {
      const dest = resolveSafe(root, path);
      ok.push({
        path,
        dest,
        size: typeof entry.size === 'number' ? entry.size : null,
      });
    } catch (error) {
      blocked.push({
        path: typeof path === 'string' ? path : null,
        reason: error.code || error.message,
      });
    }
  }

  return { ok, blocked };
}
import { extractListing } from './zipSandbox.js';

export class SandboxEngine {
  constructor() {
    this.manifest = null;
    this.last = null;
  }

  load(manifest) {
    if (!manifest || typeof manifest !== 'object' || Array.isArray(manifest)) {
      throw new TypeError('manifest must be an object');
    }
    if (typeof manifest.root !== 'string' || manifest.root.length === 0) {
      throw new TypeError('manifest.root must be a non-empty string');
    }
    if (!Array.isArray(manifest.entries)) {
      throw new TypeError('manifest.entries must be an array');
    }
    this.manifest = manifest;
    this.last = null;
  }

  run() {
    if (!this.manifest) {
      throw new Error('load a manifest before running a dry-run');
    }
    this.last = extractListing(this.manifest.entries, this.manifest.root);
    return { extracted: this.last.ok.length, blocked: this.last.blocked.length, detail: this.last };
  }
}

export function bindControls({ engine, els }) {
  const { status, log, stats, preview, btnLoad, btnRun, btnExport } = els;
  let lastExport = null;

  btnLoad.onclick = async () => {
    try {
      const res = await fetch('fixtures/manifest.json');
      if (!res.ok) {
        throw new Error(`failed to load manifest: ${res.status} ${res.statusText}`);
      }
      const data = await res.json();
      engine.load(data);
      lastExport = null;
      log.textContent = '';
      stats.textContent = '';
      status.textContent = 'ready';
      preview.textContent = JSON.stringify(data, null, 2);
    } catch (error) {
      status.textContent = error.message || String(error);
    }
  };

  btnRun.onclick = () => {
    try {
      const result = engine.run();
      lastExport = result;
      stats.textContent = `extracted=${result.extracted} blocked=${result.blocked}`;
      log.textContent = JSON.stringify(result.detail, null, 2);
      status.textContent = 'ready';
    } catch (error) {
      status.textContent = error.message || String(error);
    }
  };

  btnExport.onclick = () => {
    try {
      if (!lastExport) {
        throw new Error('run a dry-run before exporting JSON');
      }
      const json = JSON.stringify(lastExport, null, 2);
      preview.textContent = json;
      const blob = new Blob([json], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = 'zip-sandbox-dry-run.json';
      link.click();
      URL.revokeObjectURL(url);
      status.textContent = 'ready';
    } catch (error) {
      status.textContent = error.message || String(error);
    }
  };
}
import test from 'node:test';
import assert from 'node:assert/strict';
import { resolveSafe } from '../src/pathGuard.js';
test('allows nested relative path inside root', () => {
  const dest = resolveSafe('/safe/root', 'ok/a.txt');
  assert.equal(dest, '/safe/root/ok/a.txt');
});
test('blocks parent traversal', () => {
  assert.throws(() => resolveSafe('/safe/root', '../etc/passwd'));
});
test('blocks absolute entry', () => {
  assert.throws(() => resolveSafe('/safe/root', '/abs/x'));
});
test('normalizes but keeps inside root', () => {
  const dest = resolveSafe('/safe/root', 'ok/../ok/c.txt');
  assert.equal(dest, '/safe/root/ok/c.txt');
});

test('does not treat a sibling with a shared prefix as inside root', () => {
  assert.throws(() => resolveSafe('/safe/root', '../root-evil/x.txt'));
});

test('blocks Windows drive prefixes and backslash traversal', () => {
  assert.throws(() => resolveSafe('/safe/root', 'C:/evil.txt'), /drive-prefixed/);
  assert.throws(() => resolveSafe('/safe/root', '..\\..\\evil.txt'), /escapes sandbox/);
});

test('allows a safe root directory entry', () => {
  assert.equal(resolveSafe('/safe/root/', '.'), '/safe/root');
});
import test from 'node:test';
import assert from 'node:assert/strict';
import { extractListing } from '../src/zipSandbox.js';
test('separates ok and blocked', () => {
  const entries = [
    { path: 'ok/a.txt', size: 1 },
    { path: '../evil', size: 1 },
    { path: 'nested/../b.txt', size: 1 }
  ];
  const r = extractListing(entries, '/safe/root');
  assert.equal(r.ok.length, 2);
  assert.equal(r.blocked.length, 1);
  assert.equal(r.blocked[0].path, '../evil');
  assert.ok(r.blocked[0].reason);
});

test('records malformed entries instead of silently skipping them', () => {
  const result = extractListing([
    { path: 'safe.txt' },
    { path: 'C:/windows.txt' },
    null,
  ], '/safe/root');

  assert.deepEqual(result.ok, [
    { path: 'safe.txt', dest: '/safe/root/safe.txt', size: null },
  ]);
  assert.deepEqual(result.blocked.map(item => item.path), ['C:/windows.txt', null]);
  assert.ok(result.blocked.every(item => item.reason));
});

test('blocks backslash parent traversal after path planning', () => {
  const result = extractListing([{ path: 'nested\\..\\..\\evil' }], '/safe/root');
  assert.equal(result.ok.length, 0);
  assert.equal(result.blocked[0].reason, 'PATH_OUTSIDE_ROOT');
});

